"use client";

import { FormEvent, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Ban, Check, CircleDollarSign, Clock3, CloudUpload, FileCheck2, FileText, Filter, MoreHorizontal, Plus, RefreshCw, Search, Send, ShieldCheck, UsersRound, WalletCards, X } from "lucide-react";
import { createSupabaseBrowserClient } from "@/lib/supabase";
import { buildDpsDraft, isValidCpfCnpj, NFSE_OWN_APP_SERIES } from "@/lib/nfse-dps";
import type { Role } from "./app-shell";
import { TransmissionProgress } from "./transmission-progress";

type Student = { id:number; nome:string; turma:string|null; segmento:string; responsavel:string; cpf_cnpj:string|null; email:string|null; whatsapp:string|null; endereco:string|null; cep:string|null; logradouro:string|null; numero:string|null; complemento:string|null; bairro:string|null; cidade:string|null; uf:string|null };
type Payment = { id:number; aluno_id:number; competencia:string; valor_mensalidade:number; valor_nfse:number; descricao_servico:string|null; status_pagamento:string; status_nfse:string; numero_nfse:string|null; dps_xml_path:string|null; dps_xml_id:string|null; dps_xml_gerado_em:string|null; dps_assinada_xml_path:string|null; nfse_homologacao_xml_path:string|null; chave_nfse_homologacao:string|null; homologacao_emitida_em:string|null; alunos:{nome:string;responsavel:string;segmento:string;cpf_cnpj:string|null;email:string|null;whatsapp:string|null;cep:string|null;logradouro:string|null;numero:string|null;complemento:string|null;bairro:string|null;cidade:string|null;uf:string|null}|null };
type CompanyFiscalConfig = { cnpj:string|null; inscricao_municipal:string|null; razao_social:string|null; nome_fantasia?:string|null; email?:string|null; telefone?:string|null; cidade:string|null; uf:string|null; regime_tributario:string; pis_aliquota:number; cofins_aliquota:number; pis_cofins_cst:string; pis_cofins_retencao:number };
type ActiveCertificate = { validade:string; status:string; cnpj:string|null; senha_configurada:boolean };
type DpsPreview = { payment:Payment; company:CompanyFiscalConfig; service:FiscalService; series:string; number:string; description:string };
type HomologationResult = { ok?:boolean; alreadyIssued?:boolean; error?:string; key?:string };
type FiscalOperationResult = { ok?:boolean; confirmed?:boolean; error?:string; key?:string; processedAt?:string };
type NfseDocument = { id:number; mensalidade_id:number; versao:number; chave_acesso:string|null; estado:"ativa"|"cancelando"|"cancelada"|"substituindo"|"substituida"; substitui_documento_id:number|null; emitida_em:string|null };
type FiscalService = { code:string; description:string; nbs:string };
const segments=["Maternal","Jardim de Infância","Pré-escola","1º ao 5º anos","6º ao 9º anos","Ensino Médio"];
const fiscalServiceForSegment=(segment?:string|null):FiscalService=>{
 const normalized=(segment||"").toLocaleLowerCase("pt-BR");
 if(normalized.includes("médio"))return {code:"08.01.01",description:"Ensino regular médio",nbs:"122013000"};
 if(normalized.includes("1º")||normalized.includes("6º")||normalized.includes("fundamental"))return {code:"08.01.01",description:"Ensino regular fundamental",nbs:"122012000"};
 return {code:"08.01.01",description:"Ensino regular pré-escolar",nbs:"122011200"};
};
const money=(value:number)=>Number(value).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const percent=(value:number)=>Number(value).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2});
const digits=(value:string,limit:number)=>value.replace(/\D/g,"").slice(0,limit);
const formatCpfCnpj=(value:string)=>{const n=digits(value,14);if(n.length<=11)return n.replace(/^(\d{3})(\d)/,"$1.$2").replace(/^(\d{3})\.(\d{3})(\d)/,"$1.$2.$3").replace(/\.(\d{3})(\d)/,".$1-$2");return n.replace(/^(\d{2})(\d)/,"$1.$2").replace(/^(\d{2})\.(\d{3})(\d)/,"$1.$2.$3").replace(/\.(\d{3})(\d)/,".$1/$2").replace(/(\d{4})(\d)/,"$1-$2")};
const formatPhone=(value:string)=>{const n=digits(value,11);if(n.length<=10)return n.replace(/^(\d{2})(\d)/,"($1) $2").replace(/(\d{4})(\d)/,"$1-$2");return n.replace(/^(\d{2})(\d)/,"($1) $2").replace(/(\d{5})(\d)/,"$1-$2")};
const formatCurrencyInput=(value:string)=>{const cents=digits(value,13);return cents?Number(cents)/100:0};
const currencyInput=(value:string)=>{const amount=formatCurrencyInput(value);return amount?amount.toLocaleString("pt-BR",{style:"currency",currency:"BRL"}):""};
const formatCompetence=(value:string)=>{const [year,month]=value.split("-");return year&&month?`${month}/${year}`:value};
const competenceInput=(value:string)=>{const match=value.trim().match(/^(0[1-9]|1[0-2])\/(20\d{2})$/);return match?`${match[2]}-${match[1]}`:value};
const currentCompetenceInput=()=>{const parts=new Intl.DateTimeFormat("pt-BR",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit"}).formatToParts(new Date());const part=(type:"year"|"month")=>parts.find(item=>item.type===type)?.value||"";return `${part("year")}-${part("month")}`};
const dpsDraftVersionPath=(paymentId:number,draftId:string)=>{const timestamp=new Date().toISOString().replace(/\D/g,"").slice(0,17);const revision=`${timestamp}-${crypto.randomUUID().slice(0,8)}`;return `dps/${paymentId}/rascunhos/${revision}/${draftId}.xml`};
const upper=(value:string)=>value.toLocaleUpperCase("pt-BR");
const defaultServiceDescription=(competence:string,segment?:string|null)=>`MENSALIDADE ESCOLAR - COMPETÊNCIA ${formatCompetence(competence)} - ${fiscalServiceForSegment(segment).description.toLocaleUpperCase("pt-BR")}`;
const upperInput=(event:React.FormEvent<HTMLInputElement>)=>{event.currentTarget.value=upper(event.currentTarget.value)};

async function homologationErrorMessage(error:unknown){
 if(error instanceof Error&&error.name==="AbortError")return "O envio de teste ultrapassou o tempo de segurança e foi interrompido.";
 if(error instanceof Error)return error.message;
 return "O ambiente de homologação não concluiu o envio.";
}

function Heading({title,desc,action}:{title:string;desc:string;action?:React.ReactNode}) { return <div className="page-heading"><div><h1>{title}</h1><p>{desc}</p></div>{action}</div> }
function Status({children}:{children:string}) { return <span className={`status ${children.toLowerCase()}`}>{children}</span> }
function Empty({children}:{children:string}) { return <div className="empty-state"><strong>Nenhum registro encontrado</strong><p>{children}</p></div> }
function ErrorBox({message}:{message:string}) { return message?<div className="error-box page-error" role="alert">{message}</div>:null }

function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}) { return <div className="modal-backdrop"><div className="modal-card"><div className="modal-head"><h2>{title}</h2><button className="icon-button" onClick={onClose}><X/></button></div>{children}</div></div> }

export function LiveDashboard() {
 const supabase=useMemo(()=>createSupabaseBrowserClient(),[]);const [students,setStudents]=useState(0);const [payments,setPayments]=useState<Payment[]>([]);const [error,setError]=useState("");
 useEffect(()=>{if(!supabase)return;Promise.all([supabase.from("alunos").select("id",{count:"exact",head:true}),supabase.from("mensalidades").select("*, alunos(nome,responsavel,segmento,cpf_cnpj,email,cep,logradouro,numero,complemento,bairro,cidade,uf)")]).then(([a,p])=>{if(a.error||p.error)setError(a.error?.message||p.error?.message||"");else{setStudents(a.count||0);setPayments((p.data??[]) as unknown as Payment[])}})},[supabase]);
 const paid=payments.filter(p=>p.status_pagamento==="Pago").reduce((sum,p)=>sum+Number(p.valor_mensalidade),0);const pending=payments.filter(p=>p.status_pagamento==="Aberto");const prepared=payments.filter(p=>p.status_nfse!=="Pendente").length;
 return <><Heading title="Painel" desc="Visão geral dos dados reais da operação escolar e fiscal."/><div className="notice warning"><ShieldCheck/><div><strong>Ambiente fiscal protegido</strong><span>A emissão real permanece desativada até a homologação.</span></div></div><ErrorBox message={error}/><section className="stat-grid"><article className="stat-card"><span className="stat-icon blue"><UsersRound/></span><div><span>Alunos cadastrados</span><strong>{students}</strong><small>Dados do Supabase</small></div></article><article className="stat-card"><span className="stat-icon green"><CircleDollarSign/></span><div><span>Mensalidades pagas</span><strong>{money(paid)}</strong><small>{payments.filter(p=>p.status_pagamento==="Pago").length} pagamentos</small></div></article><article className="stat-card"><span className="stat-icon amber"><Clock3/></span><div><span>Mensalidades em aberto</span><strong>{pending.length}</strong><small>{money(pending.reduce((s,p)=>s+Number(p.valor_mensalidade),0))} a receber</small></div></article><article className="stat-card"><span className="stat-icon purple"><FileCheck2/></span><div><span>Notas revisadas</span><strong>{prepared}</strong><small>{payments.length} mensalidades no total</small></div></article></section>{students===0&&payments.length===0&&<div style={{marginTop:16}}><Empty>Comece cadastrando o primeiro aluno no menu “Alunos e Responsáveis”.</Empty></div>}</>
}

export function LiveStudents({role}:{role:Role}) {
 const supabase=useMemo(()=>createSupabaseBrowserClient(),[]); const [items,setItems]=useState<Student[]>([]); const [query,setQuery]=useState(""); const [open,setOpen]=useState(false); const [editingStudent,setEditingStudent]=useState<Student|null>(null); const [busy,setBusy]=useState(false); const [error,setError]=useState(""); const [address,setAddress]=useState({cep:"",logradouro:"",bairro:"",cidade:"",uf:""}); const [cepBusy,setCepBusy]=useState(false);
 const load=useCallback(async()=>{if(!supabase)return;setError("");const {data,error}=await supabase.from("alunos").select("*").order("nome");if(error)setError(error.message);else setItems(data??[])},[supabase]);
 useEffect(()=>{load()},[load]);
 async function lookupCep(raw:string){const cep=raw.replace(/\D/g,"");setAddress(a=>({...a,cep}));if(cep.length!==8)return;setCepBusy(true);setError("");try{const response=await fetch(`https://viacep.com.br/ws/${cep}/json/`);const data=await response.json();if(!response.ok||data.erro)throw new Error("CEP não encontrado.");setAddress({cep,logradouro:upper(data.logradouro||""),bairro:upper(data.bairro||""),cidade:upper(data.localidade||""),uf:upper(data.uf||"")})}catch(e){setError(e instanceof Error?e.message:"Não foi possível consultar o CEP.")}finally{setCepBusy(false)}}
 function closeStudentModal(){setOpen(false);setEditingStudent(null);setAddress({cep:"",logradouro:"",bairro:"",cidade:"",uf:""})}
 function openNewStudent(){setEditingStudent(null);setAddress({cep:"",logradouro:"",bairro:"",cidade:"",uf:""});setError("");setOpen(true)}
 function openStudentEdit(student:Student){setEditingStudent(student);setAddress({cep:student.cep||"",logradouro:student.logradouro||"",bairro:student.bairro||"",cidade:student.cidade||"",uf:student.uf||""});setError("");setOpen(true)}
 async function saveStudent(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase)return;setBusy(true);setError("");const f=new FormData(e.currentTarget);const text=(name:string)=>upper(String(f.get(name)||"")).trim();const cpfCnpj=String(f.get("cpf_cnpj")||"").trim();if(cpfCnpj&&!isValidCpfCnpj(cpfCnpj)){setBusy(false);setError("CPF/CNPJ inválido. Confira os números antes de salvar.");return}const payload={nome:text("nome"),turma:text("turma")||null,segmento:f.get("segmento"),responsavel:text("responsavel"),cpf_cnpj:cpfCnpj||null,email:String(f.get("email")||"").trim().toLocaleLowerCase("pt-BR")||null,whatsapp:f.get("whatsapp")||null,cep:address.cep||null,logradouro:text("logradouro")||null,numero:text("numero")||null,complemento:text("complemento")||null,bairro:text("bairro")||null,cidade:text("cidade")||null,uf:text("uf")||null,endereco:[text("logradouro"),text("numero"),text("complemento"),text("bairro"),text("cidade"),text("uf")].filter(Boolean).join(", ")||null};const result=editingStudent?await supabase.from("alunos").update(payload).eq("id",editingStudent.id):await supabase.from("alunos").insert(payload);setBusy(false);if(result.error){setError(result.error.message);return}closeStudentModal();await load()}
 const filtered=items.filter(i=>(i.nome+i.responsavel).toLowerCase().includes(query.toLowerCase()));
 return <><Heading title="Alunos e Responsáveis" desc="Cadastros reais armazenados com segurança no Supabase." action={role!=="Consulta"?<button className="primary" onClick={openNewStudent}><Plus size={18}/>Novo aluno</button>:undefined}/><ErrorBox message={error}/><div className="toolbar"><div className="search-input"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar por aluno ou responsável"/></div><button className="secondary"><Filter size={17}/>Filtros</button></div>{filtered.length===0?<Empty>Use “Novo aluno” para realizar o primeiro cadastro.</Empty>:<div className="table-card"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Segmento</th><th>Responsável</th><th>Contato</th><th></th></tr></thead><tbody>{filtered.map(s=><tr key={s.id}><td><strong>{s.nome}</strong></td><td>{s.turma||"—"}</td><td>{s.segmento}</td><td>{s.responsavel}<span className="subcell">{s.cpf_cnpj||"CPF não informado"}</span></td><td>{s.whatsapp||s.email||"—"}</td><td><button className="icon-button" disabled={role==="Consulta"} onClick={()=>openStudentEdit(s)} title="Editar cadastro" aria-label={`Editar cadastro de ${s.nome}`}><MoreHorizontal/></button></td></tr>)}</tbody></table></div>}{open&&<Modal title={editingStudent?"Editar aluno e responsável":"Cadastrar aluno e responsável"} onClose={closeStudentModal}><form key={editingStudent?.id||"novo"} className="data-form" onSubmit={saveStudent}><label>Nome do aluno<input name="nome" defaultValue={editingStudent?.nome||""} onInput={upperInput} required/></label><div className="form-row"><label>Turma<input name="turma" defaultValue={editingStudent?.turma||""} onInput={upperInput}/></label><label>Segmento<select name="segmento" defaultValue={editingStudent?.segmento||segments[0]} required>{segments.map(s=><option key={s}>{s}</option>)}</select></label></div><label>Responsável financeiro<input name="responsavel" defaultValue={editingStudent?.responsavel||""} onInput={upperInput} required/></label><div className="form-row"><label>CPF/CNPJ<input name="cpf_cnpj" defaultValue={editingStudent?.cpf_cnpj||""} inputMode="numeric" maxLength={18} placeholder="000.000.000-00" onChange={e=>e.currentTarget.value=formatCpfCnpj(e.currentTarget.value)}/></label><label>WhatsApp<input name="whatsapp" defaultValue={editingStudent?.whatsapp||""} inputMode="tel" maxLength={15} placeholder="(00) 00000-0000" onChange={e=>e.currentTarget.value=formatPhone(e.currentTarget.value)}/></label></div><label>E-mail<input name="email" defaultValue={editingStudent?.email||""} type="email"/></label><div className="form-row"><label>CEP<input name="cep" inputMode="numeric" maxLength={9} value={address.cep} onChange={e=>setAddress({...address,cep:e.target.value})} onBlur={e=>lookupCep(e.target.value)} placeholder="00000-000"/></label><label>Logradouro<input name="logradouro" value={address.logradouro} onChange={e=>setAddress({...address,logradouro:upper(e.target.value)})}/></label></div>{cepBusy&&<small>Consultando CEP…</small>}<div className="form-row"><label>Número<input name="numero" defaultValue={editingStudent?.numero||""} onInput={upperInput}/></label><label>Complemento<input name="complemento" defaultValue={editingStudent?.complemento||""} onInput={upperInput}/></label></div><div className="form-row"><label>Bairro<input name="bairro" value={address.bairro} onChange={e=>setAddress({...address,bairro:upper(e.target.value)})}/></label><label>Cidade<input name="cidade" value={address.cidade} onChange={e=>setAddress({...address,cidade:upper(e.target.value)})}/></label></div><label>UF<input name="uf" maxLength={2} value={address.uf} onChange={e=>setAddress({...address,uf:upper(e.target.value)})}/></label><div className="form-actions"><button type="button" className="secondary" onClick={closeStudentModal}>Cancelar</button><button className="primary" disabled={busy}>{busy?"Salvando…":editingStudent?"Salvar alterações":"Salvar cadastro"}</button></div></form></Modal>}</>
}

export function LivePayments({role}:{role:Role}) {
 const supabase=useMemo(()=>createSupabaseBrowserClient(),[]); const [items,setItems]=useState<Payment[]>([]);const [students,setStudents]=useState<Student[]>([]);const [open,setOpen]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [paymentStatus,setPaymentStatus]=useState("Aberto");const [formStudentId,setFormStudentId]=useState("");const [formCompetence,setFormCompetence]=useState("");const [serviceDescription,setServiceDescription]=useState("");const [descriptionEdited,setDescriptionEdited]=useState(false);
 const load=useCallback(async()=>{if(!supabase)return;setError("");const [p,s]=await Promise.all([supabase.from("mensalidades").select("*, alunos(nome,responsavel,segmento,cpf_cnpj,email,cep,logradouro,numero,complemento,bairro,cidade,uf)").order("created_at",{ascending:false}),supabase.from("alunos").select("*").order("nome")]);if(p.error)setError(p.error.message);else setItems((p.data??[]) as unknown as Payment[]);if(!s.error)setStudents(s.data??[])},[supabase]);useEffect(()=>{load()},[load]);
 function automaticDescription(studentId=formStudentId,competence=formCompetence){const student=students.find(s=>String(s.id)===studentId);return student&&competence?defaultServiceDescription(competence,student.segmento):""}
 function closeModal(){setOpen(false);setPaymentStatus("Aberto");setFormStudentId("");setFormCompetence("");setServiceDescription("");setDescriptionEdited(false)}
 async function create(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase)return;setBusy(true);setError("");const f=new FormData(e.currentTarget);const competence=String(f.get("competencia"));if(!competence||competence>currentCompetenceInput()){setBusy(false);setError("A competência não pode ser posterior ao mês atual.");return}const value=formatCurrencyInput(String(f.get("valor")));const description=upper(serviceDescription||automaticDescription()).trim();const payload={aluno_id:Number(f.get("aluno_id")),competencia:formatCompetence(competence),valor_mensalidade:value,valor_nfse:value,descricao_servico:description,status_pagamento:f.get("status_pagamento")};const {error}=await supabase.from("mensalidades").insert(payload);setBusy(false);if(error){setError(error.message);return}closeModal();await load()}
 return <><Heading title="Mensalidades" desc="Cobranças reais; o valor inicial da NFS-e é copiado automaticamente." action={role==="Administrador"||role==="Financeiro"?<button className="primary" onClick={()=>{closeModal();setOpen(true)}}><Plus size={18}/>Nova cobrança</button>:undefined}/><ErrorBox message={error}/>{items.length===0?<Empty>Cadastre um aluno e depois registre sua primeira mensalidade.</Empty>:<div className="table-card"><table><thead><tr><th>Aluno</th><th>Competência</th><th>Mensalidade</th><th>Valor NFS-e</th><th>Pagamento</th><th>NFS-e</th></tr></thead><tbody>{items.map(p=><tr key={p.id}><td><strong>{p.alunos?.nome||`Aluno #${p.aluno_id}`}</strong></td><td>{p.competencia}</td><td>{money(p.valor_mensalidade)}</td><td>{money(p.valor_nfse)}</td><td><Status>{p.status_pagamento==="Aberto"?"Pendente":p.status_pagamento}</Status></td><td><Status>{p.status_nfse}</Status></td></tr>)}</tbody></table></div>}{open&&<Modal title="Registrar mensalidade" onClose={closeModal}><form className="data-form" onSubmit={create}><label>Aluno<select name="aluno_id" required value={formStudentId} onChange={e=>{const studentId=e.target.value;setFormStudentId(studentId);if(!descriptionEdited){const student=students.find(s=>String(s.id)===studentId);setServiceDescription(student&&formCompetence?defaultServiceDescription(formCompetence,student.segmento):"")}}}><option value="">Selecione</option>{students.map(s=><option value={s.id} key={s.id}>{s.nome}</option>)}</select></label><div className="form-row"><label>Competência<input name="competencia" type="month" max={currentCompetenceInput()} required value={formCompetence} onChange={e=>{const competence=e.target.value;setFormCompetence(competence);if(!descriptionEdited){const student=students.find(s=>String(s.id)===formStudentId);setServiceDescription(student&&competence?defaultServiceDescription(competence,student.segmento):"")}}}/></label><label>Valor<input name="valor" type="text" inputMode="numeric" placeholder="R$ 0,00" onInput={e=>e.currentTarget.value=currencyInput(e.currentTarget.value)} required/></label></div><label>Descrição do Serviço<textarea name="descricao_servico" rows={4} maxLength={1000} placeholder="Descreva o serviço que deverá constar na nota" value={serviceDescription} onChange={e=>{setDescriptionEdited(true);setServiceDescription(upper(e.target.value))}} required/><small>O texto é sugerido automaticamente e poderá ser alterado antes da emissão.</small></label><label>Status do pagamento<select name="status_pagamento" className={`payment-status ${paymentStatus==="Pago"?"paid":"pending"}`} value={paymentStatus} onChange={e=>setPaymentStatus(e.target.value)}><option value="Aberto">Pendente</option><option value="Pago">Pago</option></select></label><div className="notice compact"><WalletCards/><span>O valor e a descrição da NFS-e poderão ser revisados antes da futura emissão.</span></div><div className="form-actions"><button type="button" className="secondary" onClick={closeModal}>Cancelar</button><button className="primary" disabled={busy||students.length===0}>{busy?"Salvando…":"Salvar mensalidade"}</button></div></form></Modal>}</>
}

export function LiveInvoices({role}:{role:Role}) {
 const supabase=useMemo(()=>createSupabaseBrowserClient(),[]);const [allItems,setItems]=useState<Payment[]>([]);const [documents,setDocuments]=useState<NfseDocument[]>([]);const [editing,setEditing]=useState<number|null>(null);const [value,setValue]=useState("");const [error,setError]=useState("");const [message,setMessage]=useState("");const [validating,setValidating]=useState<number|null>(null);const [preview,setPreview]=useState<DpsPreview|null>(null);const [approving,setApproving]=useState(false);const [generating,setGenerating]=useState(false);const [openingXml,setOpeningXml]=useState<number|null>(null);const [storedXml,setStoredXml]=useState<{title:string;subtitle:string;xml:string}|null>(null);const [homologationPayment,setHomologationPayment]=useState<Payment|null>(null);const [sendingHomologation,setSendingHomologation]=useState(false);const homologationRequestInFlight=useRef(false);const [correctingPayment,setCorrectingPayment]=useState<Payment|null>(null);const [correcting,setCorrecting]=useState(false);const [cancellingPayment,setCancellingPayment]=useState<Payment|null>(null);const [substitutingPayment,setSubstitutingPayment]=useState<Payment|null>(null);const [fiscalOperationBusy,setFiscalOperationBusy]=useState(false);const fiscalOperationInFlight=useRef(false);
 const [nfseSearch,setNfseSearch]=useState("");const [nfsePeriod,setNfsePeriod]=useState("");const [nfseStatus,setNfseStatus]=useState("todas");
 const load=useCallback(async()=>{if(!supabase)return;const [paymentsResult,documentsResult]=await Promise.all([supabase.from("mensalidades").select("*, alunos(nome,responsavel,segmento,cpf_cnpj,email,whatsapp,cep,logradouro,numero,complemento,bairro,cidade,uf)").order("created_at",{ascending:false}),supabase.from("nfse_documentos_homologacao").select("id,mensalidade_id,versao,chave_acesso,estado,substitui_documento_id,emitida_em").order("versao",{ascending:false})]);if(paymentsResult.error)setError(paymentsResult.error.message);else setItems((paymentsResult.data??[]) as unknown as Payment[]);if(documentsResult.error)setError(documentsResult.error.message);else setDocuments((documentsResult.data??[]) as NfseDocument[])},[supabase]);useEffect(()=>{load()},[load]);
 const documentsByPayment=useMemo(()=>{const grouped=new Map<number,NfseDocument[]>();for(const document of documents){const versions=grouped.get(document.mensalidade_id);if(versions)versions.push(document);else grouped.set(document.mensalidade_id,[document])}return grouped},[documents]);
 const competenceOptions=useMemo(()=>Array.from(new Set(allItems.map(item=>item.competencia))).sort((a,b)=>competenceInput(b).localeCompare(competenceInput(a))),[allItems]);
 const filteredItems=useMemo(()=>{const query=nfseSearch.trim().toLocaleLowerCase("pt-BR");return allItems.filter(payment=>{const versions=documentsByPayment.get(payment.id)||[];const activeDocument=versions.find(document=>document.estado==="ativa");const normalizedStatus=payment.status_nfse.toLocaleLowerCase("pt-BR");const searchText=[payment.alunos?.nome,payment.alunos?.responsavel,payment.competencia,payment.numero_nfse,payment.chave_nfse_homologacao,...versions.map(document=>document.chave_acesso)].filter(Boolean).join(" ").toLocaleLowerCase("pt-BR");const matchesSearch=!query||searchText.includes(query);const matchesPeriod=!nfsePeriod||payment.competencia===nfsePeriod;const matchesStatus=nfseStatus==="todas"||(nfseStatus==="preparacao"&&!payment.chave_nfse_homologacao&&!normalizedStatus.includes("rejeitada"))||(nfseStatus==="ativas"&&Boolean(activeDocument))||(nfseStatus==="substituidas"&&versions.some(document=>document.estado==="substituida"))||(nfseStatus==="canceladas"&&(normalizedStatus.includes("cancelada")||(!activeDocument&&versions.some(document=>document.estado==="cancelada"))))||(nfseStatus==="rejeitadas"&&normalizedStatus.includes("rejeitada"));return matchesSearch&&matchesPeriod&&matchesStatus})},[allItems,documentsByPayment,nfsePeriod,nfseSearch,nfseStatus]);
 const filteredIssuedItems=useMemo(()=>filteredItems.filter(payment=>Boolean(payment.chave_nfse_homologacao)),[filteredItems]);
 const filtersActive=Boolean(nfseSearch||nfsePeriod||nfseStatus!=="todas");
 const items=filteredItems;
 async function save(p:Payment){if(!supabase)return;const next=Number(value.replace(",","."));if(!next||next<=0){setError("Informe um valor válido.");return}const {error}=await supabase.from("mensalidades").update({valor_nfse:next,status_nfse:"Revisada"}).eq("id",p.id);if(error){setError(error.message);return}await supabase.from("historico_nfse").insert({mensalidade_id:p.id,evento:"valor_nfse_alterado",valor_anterior:p.valor_nfse,valor_novo:next,detalhes:"Alteração manual antes da emissão"});setEditing(null);await load()}
 async function saveCorrection(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!supabase||!correctingPayment)return;setCorrecting(true);setError("");setMessage("");const form=new FormData(event.currentTarget);const competence=String(form.get("competencia")||"");const nextValue=formatCurrencyInput(String(form.get("valor")||""));const description=upper(String(form.get("descricao_servico")||"")).trim();if(!competence||competence>currentCompetenceInput()){setCorrecting(false);setError("A competência não pode ser posterior ao mês atual.");return}if(nextValue<=0){setCorrecting(false);setError("Informe um valor válido para a NFS-e.");return}if(!description||description.length>1000){setCorrecting(false);setError("A descrição do serviço deve ter entre 1 e 1000 caracteres.");return}const payment=correctingPayment;const updateResult=await supabase.from("mensalidades").update({competencia:formatCompetence(competence),valor_nfse:nextValue,descricao_servico:description,status_nfse:"Revisada",dps_xml_path:null,dps_xml_id:null,dps_xml_gerado_em:null,dps_assinada_xml_path:null,nfse_homologacao_xml_path:null,chave_nfse_homologacao:null,homologacao_emitida_em:null}).eq("id",payment.id).is("chave_nfse_homologacao",null).select("id").maybeSingle();if(updateResult.error||!updateResult.data){setCorrecting(false);setError(updateResult.error?.message||"Esta nota já foi autorizada e não pode mais ser corrigida.");return}const details=`Dados corrigidos após rejeição. Competência ${payment.competencia} → ${formatCompetence(competence)}; valor ${money(payment.valor_nfse)} → ${money(nextValue)}. A tentativa rejeitada e seus XMLs foram preservados no histórico. Nova validação obrigatória antes do reenvio.`;const historyResult=await supabase.from("historico_nfse").insert({mensalidade_id:payment.id,evento:"dados_nfse_corrigidos",valor_anterior:payment.valor_nfse,valor_novo:nextValue,detalhes:details});setCorrecting(false);setCorrectingPayment(null);if(historyResult.error){setError(`Os dados foram corrigidos, mas o histórico não pôde ser gravado: ${historyResult.error.message}`);await load();return}setMessage("Dados corrigidos. Valide novamente a nota antes de gerar e reenviar a DPS.");await load()}
 async function validateForHomologation(p:Payment){
  if(!supabase)return;setValidating(p.id);setError("");setMessage("");
  const [companyResult,certificateResult]=await Promise.all([
    supabase.from("configuracoes_empresa").select("cnpj,inscricao_municipal,razao_social,cidade,uf,regime_tributario,pis_aliquota,cofins_aliquota,pis_cofins_cst,pis_cofins_retencao").eq("id",true).maybeSingle(),
   supabase.from("certificados_a1").select("validade,status,cnpj,senha_configurada").eq("status","ATIVO").order("created_at",{ascending:false}).limit(1).maybeSingle(),
  ]);
  if(companyResult.error||certificateResult.error){setError(companyResult.error?.message||certificateResult.error?.message||"Não foi possível conferir os dados fiscais.");setValidating(null);return}
  const company=companyResult.data as CompanyFiscalConfig|null;const certificate=certificateResult.data as ActiveCertificate|null;const missing:string[]=[];const student=p.alunos;
   if(!company?.cnpj)missing.push("CNPJ da empresa");if(!company?.razao_social)missing.push("razão social");if(!company?.cidade||!company?.uf)missing.push("município da empresa");
   if(company?.regime_tributario!=="LUCRO PRESUMIDO")missing.push("regime tributário Lucro Presumido");if(!Number.isFinite(Number(company?.pis_aliquota))||Number(company?.pis_aliquota)<0||Number(company?.pis_aliquota)>100)missing.push("alíquota válida de PIS");if(!Number.isFinite(Number(company?.cofins_aliquota))||Number(company?.cofins_aliquota)<0||Number(company?.cofins_aliquota)>100)missing.push("alíquota válida de COFINS");if(!/^\d{2}$/.test(company?.pis_cofins_cst||""))missing.push("CST válido do PIS/COFINS");if(!Number.isInteger(Number(company?.pis_cofins_retencao))||Number(company?.pis_cofins_retencao)<0||Number(company?.pis_cofins_retencao)>9)missing.push("retenção válida do PIS/COFINS");
  if(!certificate)missing.push("certificado A1 ativo");else if(new Date(`${certificate.validade}T23:59:59`).getTime()<Date.now())missing.push("certificado A1 válido");else if(!certificate.senha_configurada)missing.push("senha protegida do certificado A1");
  if(!student?.responsavel)missing.push("responsável financeiro");if(!student?.cpf_cnpj)missing.push("CPF/CNPJ do tomador");else if(!isValidCpfCnpj(student.cpf_cnpj))missing.push("CPF/CNPJ válido do tomador");if(!student?.email)missing.push("e-mail do tomador");if(!student?.cep||!student?.logradouro||!student?.numero||!student?.cidade||!student?.uf)missing.push("endereço completo do tomador");
  const normalizedCompetence=competenceInput(p.competencia);if(!/^20\d{2}-(0[1-9]|1[0-2])$/.test(normalizedCompetence))missing.push("competência válida");else if(normalizedCompetence>currentCompetenceInput())missing.push("competência não posterior ao mês atual");if(Number(p.valor_nfse)<=0)missing.push("valor da NFS-e");
  if(missing.length){setError(`Para validar esta nota, complete: ${missing.join(", ")}.`);setValidating(null);return}
  const service=fiscalServiceForSegment(student?.segmento);const details=`Validação local de homologação aprovada. Serviço ${service.code} - ${service.description}. Nenhuma transmissão realizada.`;
  const updateResult=await supabase.from("mensalidades").update({status_nfse:"Homologação validada"}).eq("id",p.id);
  if(updateResult.error){setError(updateResult.error.message);setValidating(null);return}
  const historyResult=await supabase.from("historico_nfse").insert({mensalidade_id:p.id,evento:"validacao_homologacao_aprovada",valor_anterior:p.valor_nfse,valor_novo:p.valor_nfse,detalhes:details});
  if(historyResult.error){setError(`A nota foi validada, mas o histórico não pôde ser gravado: ${historyResult.error.message}`);setValidating(null);await load();return}
  setMessage(`Dados de ${student?.nome||"aluno"} validados para homologação. Nenhuma nota foi transmitida.`);setValidating(null);await load();
 }
  async function openDpsPreview(p:Payment){if(!supabase)return;setError("");const {data,error}=await supabase.from("configuracoes_empresa").select("cnpj,inscricao_municipal,razao_social,nome_fantasia,email,telefone,cidade,uf,regime_tributario,pis_aliquota,cofins_aliquota,pis_cofins_cst,pis_cofins_retencao").eq("id",true).maybeSingle();if(error||!data){setError(error?.message||"Configuração da empresa não encontrada.");return}const service=fiscalServiceForSegment(p.alunos?.segmento);setPreview({payment:p,company:data,service,series:NFSE_OWN_APP_SERIES,number:String(p.id),description:p.descricao_servico||defaultServiceDescription(p.competencia,p.alunos?.segmento)})}
  async function approveDpsPreview(){if(!supabase||!preview)return;const description=upper(preview.description).trim();if(!description){setError("Informe a Descrição do Serviço que deverá constar na nota.");return}setApproving(true);setError("");const p=preview.payment;const alreadyApproved=p.status_nfse==="Prévia DPS aprovada";const updateResult=await supabase.from("mensalidades").update({status_nfse:"Prévia DPS aprovada",descricao_servico:description}).eq("id",p.id);if(updateResult.error){setError(updateResult.error.message);setApproving(false);return}const details=`${alreadyApproved?"Descrição do serviço atualizada":"Prévia DPS aprovada"} sem transmissão. Ambiente 2 - Produção restrita; Série ${preview.series}; Número ${preview.number}; Serviço ${preview.service.code}; Descrição: ${description}; ISS 5,00%; NBS 122012000; Regime ${preview.company.regime_tributario}; PIS ${percent(preview.company.pis_aliquota)}%; COFINS ${percent(preview.company.cofins_aliquota)}%; CST ${preview.company.pis_cofins_cst}; Retenção ${preview.company.pis_cofins_retencao}.`;const historyResult=await supabase.from("historico_nfse").insert({mensalidade_id:p.id,evento:alreadyApproved?"descricao_servico_atualizada":"previa_dps_aprovada",valor_anterior:p.valor_nfse,valor_novo:p.valor_nfse,detalhes:details});setApproving(false);if(historyResult.error){setError(`Os dados foram salvos, mas o histórico não pôde ser gravado: ${historyResult.error.message}`);await load();return}setPreview(null);setMessage(alreadyApproved?`Descrição do serviço de ${p.alunos?.nome||"aluno"} atualizada. Nenhuma nota foi transmitida.`:`Prévia DPS de ${p.alunos?.nome||"aluno"} aprovada e gravada no histórico. Nenhuma nota foi transmitida.`);await load()}
  async function generateDpsXml(){if(!supabase||!preview)return;setGenerating(true);setError("");const p=preview.payment;const description=upper(preview.description).trim();let storedPath="";try{const draft=buildDpsDraft({municipalityCode:"3304557",series:preview.series,number:preview.number,competence:p.competencia,provider:{cnpj:preview.company.cnpj||"",municipalRegistration:null,name:preview.company.razao_social},taker:{taxId:p.alunos?.cpf_cnpj||"",name:p.alunos?.responsavel||"",email:p.alunos?.email,phone:p.alunos?.whatsapp},service:{nationalTaxCode:preview.service.code,nbs:preview.service.nbs,description,amount:Number(p.valor_nfse),issRate:5,federalTaxes:{cst:preview.company.pis_cofins_cst,pisRate:Number(preview.company.pis_aliquota),cofinsRate:Number(preview.company.cofins_aliquota),withholdingType:Number(preview.company.pis_cofins_retencao)},ibsCbs:{operationIndicator:"030101",taxStatus:"200",taxClassification:"200028"}}});storedPath=dpsDraftVersionPath(p.id,draft.id);const blob=new Blob([draft.xml],{type:"application/xml"});const uploadResult=await supabase.storage.from("documentos-nfse").upload(storedPath,blob,{contentType:"application/xml",upsert:false});if(uploadResult.error)throw new Error(`Não foi possível guardar o XML: ${uploadResult.error.message}`);const generatedAt=new Date().toISOString();const updateResult=await supabase.from("mensalidades").update({status_nfse:"XML DPS armazenado",descricao_servico:description,dps_xml_path:storedPath,dps_xml_id:draft.id,dps_xml_gerado_em:generatedAt}).eq("id",p.id);if(updateResult.error){await supabase.storage.from("documentos-nfse").remove([storedPath]);throw new Error(updateResult.error.message)}const historyResult=await supabase.from("historico_nfse").insert({mensalidade_id:p.id,evento:"xml_dps_armazenado",valor_anterior:p.valor_nfse,valor_novo:p.valor_nfse,detalhes:`XML DPS ${draft.version} com Lucro Presumido, PIS/COFINS e IBS/CBS armazenado no repositório privado do sistema, sem assinatura e sem transmissão. Identificador ${draft.id}; arquivo ${storedPath}.`});if(historyResult.error)throw new Error(`O XML foi guardado, mas o histórico não pôde ser gravado: ${historyResult.error.message}`);setPreview(null);setMessage(`XML da DPS de ${p.alunos?.nome||"aluno"} guardado no sistema online. Nenhum download foi necessário e nenhuma nota foi transmitida.`);await load()}catch(cause){setError(cause instanceof Error?cause.message:"Não foi possível guardar o XML da DPS.")}finally{setGenerating(false)}}
 async function openStoredXml(p:Payment,path:string|null,title:string,subtitle:string){if(!supabase||!path)return;setOpeningXml(p.id);setError("");const {data,error}=await supabase.storage.from("documentos-nfse").download(path);setOpeningXml(null);if(error||!data){setError(error?.message||"Não foi possível abrir o XML guardado.");return}setStoredXml({title,subtitle,xml:await data.text()})}
 function closeHomologation(){if(sendingHomologation)return;setHomologationPayment(null)}
 async function sendToHomologation(event:FormEvent<HTMLFormElement>){
 event.preventDefault();
  if(!supabase||!homologationPayment||homologationRequestInFlight.current)return;
  const payment=homologationPayment;
  homologationRequestInFlight.current=true;
  setSendingHomologation(true);
  setError("");
  setMessage("");
  const controller=new AbortController();
  const timeout=window.setTimeout(()=>controller.abort(),55000);
  try{
    const {data:{session}}=await supabase.auth.getSession();
    if(!session)throw new Error("Sua sessão expirou. Entre novamente.");
    const response=await fetch("/api/nfse/homologation/issue",{
      method:"POST",
      headers:{Authorization:`Bearer ${session.access_token}`,"Content-Type":"application/json"},
      body:JSON.stringify({monthlyId:payment.id}),
      signal:controller.signal,
      cache:"no-store",
    });
    const data=await response.json().catch(()=>({})) as HomologationResult;
    if(!response.ok)throw new Error(data.error||"A produção restrita não concluiu a homologação.");
    if(!data?.ok)throw new Error(data?.error||"A produção restrita não confirmou a emissão.");
    const student=payment.alunos?.nome||"aluno";
    setMessage(data.alreadyIssued
      ?`A NFS-e de teste de ${student} já estava guardada no sistema.`
      :`NFS-e de teste de ${student} gerada na produção restrita e guardada online. Chave: ${data.key}.`
    );
    setHomologationPayment(null);
    await load();
  }catch(cause){
    setHomologationPayment(null);
    const reason=await homologationErrorMessage(cause);
    setError(`${reason} Nenhuma NFS-e foi emitida. Você pode tentar novamente nesta mesma mensalidade.`);
    await load();
  }finally{
    window.clearTimeout(timeout);
    homologationRequestInFlight.current=false;
    setSendingHomologation(false);
 }
}
 async function cancelHomologationInvoice(event:FormEvent<HTMLFormElement>){
  event.preventDefault();if(!supabase||!cancellingPayment||fiscalOperationInFlight.current)return;
  const payment=cancellingPayment;const form=new FormData(event.currentTarget);const reasonCode=String(form.get("reasonCode")||"");const reason=String(form.get("reason")||"").trim();
  if(reason.length<15){setError("Descreva o motivo do cancelamento com pelo menos 15 caracteres.");return}
  fiscalOperationInFlight.current=true;setFiscalOperationBusy(true);setError("");setMessage("");
  const controller=new AbortController();const timeout=window.setTimeout(()=>controller.abort(),55000);
  try{const {data:{session}}=await supabase.auth.getSession();if(!session)throw new Error("Sua sessão expirou. Entre novamente.");const response=await fetch("/api/nfse/homologation/cancel",{method:"POST",headers:{Authorization:`Bearer ${session.access_token}`,"Content-Type":"application/json"},body:JSON.stringify({monthlyId:payment.id,reasonCode,reason}),signal:controller.signal,cache:"no-store"});const data=await response.json().catch(()=>({})) as FiscalOperationResult;if(!response.ok&&!data.confirmed)throw new Error(data.error||"A produção restrita não concluiu o cancelamento.");setCancellingPayment(null);setMessage(data.confirmed&&!data.ok?"Cancelamento confirmado pela SEFIN; os arquivos locais estão sendo sincronizados.":`NFS-e de teste de ${payment.alunos?.nome||"aluno"} cancelada com sucesso.`);await load()}catch(cause){setCancellingPayment(null);setError(await homologationErrorMessage(cause));await load()}finally{window.clearTimeout(timeout);fiscalOperationInFlight.current=false;setFiscalOperationBusy(false)}
 }
 async function substituteHomologationInvoice(event:FormEvent<HTMLFormElement>){
  event.preventDefault();if(!supabase||!substitutingPayment||fiscalOperationInFlight.current)return;
  const payment=substitutingPayment;const form=new FormData(event.currentTarget);const competence=String(form.get("competencia")||"");const amount=formatCurrencyInput(String(form.get("valor")||""));const description=upper(String(form.get("descricao_servico")||"")).trim();const reasonCode=String(form.get("reasonCode")||"");const reason=String(form.get("reason")||"").trim();
  if(!competence||competence>currentCompetenceInput()){setError("A competência não pode ser posterior ao mês atual.");return}if(amount<=0){setError("Informe um valor válido para a nota substituta.");return}if(!description){setError("Informe a descrição corrigida do serviço.");return}if(reason.length<15){setError("Descreva o motivo da substituição com pelo menos 15 caracteres.");return}
  fiscalOperationInFlight.current=true;setFiscalOperationBusy(true);setError("");setMessage("");
  const controller=new AbortController();const timeout=window.setTimeout(()=>controller.abort(),55000);
  try{const {data:{session}}=await supabase.auth.getSession();if(!session)throw new Error("Sua sessão expirou. Entre novamente.");const response=await fetch("/api/nfse/homologation/issue",{method:"POST",headers:{Authorization:`Bearer ${session.access_token}`,"Content-Type":"application/json"},body:JSON.stringify({monthlyId:payment.id,operation:"substitute",competence:formatCompetence(competence),amount,description,reasonCode,reason}),signal:controller.signal,cache:"no-store"});const data=await response.json().catch(()=>({})) as FiscalOperationResult;if(!response.ok&&!data.confirmed)throw new Error(data.error||"A produção restrita não concluiu a substituição.");setSubstitutingPayment(null);setMessage(data.confirmed&&!data.ok?"Substituição confirmada pela SEFIN; os arquivos locais estão sendo sincronizados.":`Nota corrigida e substituída com sucesso. Nova chave: ${data.key}.`);await load()}catch(cause){setSubstitutingPayment(null);setError(await homologationErrorMessage(cause));await load()}finally{window.clearTimeout(timeout);fiscalOperationInFlight.current=false;setFiscalOperationBusy(false)}
 }
 const canManage=role==="Administrador"||role==="Financeiro";
 return <>
  <Heading title="NFS-e" desc="Preparação, armazenamento e revisão das notas no ambiente online."/>
  <div className="notice warning"><ShieldCheck/><div><strong>Emissão fiscal real permanece bloqueada</strong><span>Somente notas de teste podem ser enviadas à produção restrita. Todos os XMLs ficam guardados de forma privada no sistema.</span></div></div>
  <ErrorBox message={error}/>{message&&<div className="success-box" role="status">{message}</div>}
  {allItems.length>0&&<section className="nfse-filter-panel" aria-label="Filtros da lista de NFS-e"><div className="nfse-filter-heading"><div><Filter/><span><strong>Organizar NFS-e</strong><small>Os mesmos filtros também organizam os ajustes das notas emitidas.</small></span></div><div className="nfse-filter-count"><strong>{filteredItems.length}</strong><span>de {allItems.length} notas</span><small>{filteredIssuedItems.length} emitidas no resultado</small></div></div><div className="nfse-filter-grid"><label className="nfse-filter-search"><span>Aluno, responsável ou chave</span><div><Search/><input value={nfseSearch} onChange={event=>setNfseSearch(event.target.value)} placeholder="Digite para buscar"/></div></label><label><span>Período / competência</span><select value={nfsePeriod} onChange={event=>setNfsePeriod(event.target.value)}><option value="">Todos os períodos</option>{competenceOptions.map(competence=><option value={competence} key={competence}>{competence}</option>)}</select></label><label><span>Situação</span><select value={nfseStatus} onChange={event=>setNfseStatus(event.target.value)}><option value="todas">Todas as situações</option><option value="preparacao">Em preparação</option><option value="ativas">Ativas em homologação</option><option value="substituidas">Com substituição</option><option value="canceladas">Canceladas</option><option value="rejeitadas">Rejeitadas</option></select></label><button type="button" className="secondary nfse-clear-filters" disabled={!filtersActive} onClick={()=>{setNfseSearch("");setNfsePeriod("");setNfseStatus("todas")}}>Limpar filtros</button></div>{filtersActive&&<div className="nfse-filter-active" role="status"><Filter/>Filtros aplicados · mostrando {filteredItems.length} {filteredItems.length===1?"nota":"notas"}</div>}</section>}
  {items.length===0?<Empty>As notas aparecerão automaticamente quando houver mensalidades cadastradas.</Empty>:<div className="table-card"><table><thead><tr><th>Aluno / Tomador</th><th>Competência</th><th>Serviço fiscal</th><th>Valor NFS-e</th><th>Situação</th><th>Homologação</th></tr></thead><tbody>{items.map(p=>{const service=fiscalServiceForSegment(p.alunos?.segmento);const ready=p.status_nfse==="Homologação validada"||p.status_nfse==="Prévia DPS aprovada"||p.status_nfse==="XML DPS preparado"||p.status_nfse==="XML DPS armazenado";const activeDocument=(documentsByPayment.get(p.id)||[]).find(document=>document.estado==="ativa");const displayStatus=activeDocument?`NFS-e ativa em homologação · versão ${activeDocument.versao}`:p.status_nfse;return <tr key={p.id}><td><strong>{p.alunos?.nome||`Aluno #${p.aluno_id}`}</strong><span className="subcell">{p.alunos?.responsavel||"Responsável cadastrado"}</span></td><td>{p.competencia}</td><td><strong>{service.code}</strong><span className="subcell">{service.description}</span><span className="auto-tag"><WalletCards size={14}/>Automático</span></td><td>{editing===p.id?<div className="inline-edit"><span>R$</span><input autoFocus value={value} onChange={e=>setValue(e.target.value)}/><button onClick={()=>save(p)}><Check/></button></div>:<button className="editable-value" disabled={!canManage||Boolean(p.chave_nfse_homologacao)} onClick={()=>{setEditing(p.id);setValue(String(p.valor_nfse).replace(".",","))}}>{money(p.valor_nfse)} {!p.chave_nfse_homologacao&&<small>editar</small>}</button>}</td><td><Status>{displayStatus}</Status>{activeDocument&&activeDocument.versao>1&&<span className="subcell">A versão anterior permanece preservada no histórico.</span>}{p.homologacao_emitida_em?<span className="subcell">Teste emitido em {new Date(p.homologacao_emitida_em).toLocaleString("pt-BR")}</span>:p.dps_xml_gerado_em&&<span className="subcell">Guardado em {new Date(p.dps_xml_gerado_em).toLocaleString("pt-BR")}</span>}</td><td>{p.status_nfse==="Rejeitada em homologação"?<div className="nfse-actions">{p.dps_xml_path&&<button className="secondary" disabled={openingXml===p.id} onClick={()=>openStoredXml(p,p.dps_xml_path,"Última DPS rejeitada",`${p.dps_xml_id} · Tentativa preservada para conferência.`)}><FileText size={16}/>{openingXml===p.id?"Abrindo…":"Ver última DPS"}</button>}{canManage?<button className="primary compact-button" onClick={()=>{setError("");setMessage("");setCorrectingPayment(p)}}><FileText size={16}/>Corrigir para reenviar</button>:<span className="muted">Somente leitura</span>}</div>:p.dps_xml_path?<div className="nfse-actions"><button className="secondary" disabled={openingXml===p.id} onClick={()=>openStoredXml(p,p.dps_xml_path,"XML da DPS armazenado",`${p.dps_xml_id} · Arquivo privado sem download obrigatório.`)}><FileText size={16}/>{openingXml===p.id?"Abrindo…":"Ver DPS"}</button>{p.nfse_homologacao_xml_path?<button className="secondary" disabled={openingXml===p.id} onClick={()=>openStoredXml(p,p.nfse_homologacao_xml_path,"NFS-e de teste armazenada",`Produção restrita · Chave ${p.chave_nfse_homologacao}.`)}><FileCheck2 size={16}/>Ver NFS-e de teste</button>:canManage&&<button className="primary compact-button" onClick={()=>{setError("");setMessage("");setHomologationPayment(p)}}><Send size={16}/>Enviar à homologação</button>}{canManage&&!p.chave_nfse_homologacao&&<button className="text-button" onClick={()=>openDpsPreview(p)}>Atualizar DPS</button>}</div>:canManage?(ready?<button className="secondary" onClick={()=>openDpsPreview(p)}>{p.status_nfse==="XML DPS preparado"?"Guardar XML online":p.status_nfse==="Prévia DPS aprovada"?"Ver e editar prévia":"Gerar prévia DPS"}</button>:<button className="secondary" disabled={validating===p.id} onClick={()=>validateForHomologation(p)}>{validating===p.id?"Validando…":"Validar dados"}</button>):<span className="muted">Somente leitura</span>}</td></tr>})}</tbody></table></div>}
  {canManage&&items.some(p=>Boolean(p.chave_nfse_homologacao))&&<section className="panel nfse-management"><div className="panel-title"><div><h2>Ajustes em notas emitidas</h2><p>A versão atual fica destacada e todas as versões anteriores permanecem disponíveis no histórico.</p></div></div><div className="nfse-management-list">{items.filter(p=>Boolean(p.chave_nfse_homologacao)).map(p=>{const versions=documentsByPayment.get(p.id)||[];const activeDocument=versions.find(document=>document.estado==="ativa");const latestDocument=versions[0];const normalized=p.status_nfse.toLocaleLowerCase("pt-BR");const blocked=!activeDocument||normalized.includes("cancelada")||normalized.includes("processamento")||normalized.includes("pendente");return <article key={p.id}><div><strong>{p.alunos?.nome||`Aluno #${p.aluno_id}`}</strong><span>{p.competencia} · {money(p.valor_nfse)}</span><small>Chave {(activeDocument?.chave_acesso||p.chave_nfse_homologacao)?.slice(0,8)}…{(activeDocument?.chave_acesso||p.chave_nfse_homologacao)?.slice(-6)}</small>{versions.length>0&&<details className="nfse-version-history"><summary>Ver histórico de {versions.length} {versions.length===1?"versão":"versões"}</summary>{versions.map(document=><div key={document.id}><strong>Versão {document.versao}</strong><span>{document.estado==="ativa"?"Ativa em homologação":document.estado==="substituida"?"Substituída e preservada":document.estado==="cancelada"?"Cancelada e preservada":document.estado}</span></div>)}</details>}</div><div className="nfse-current-version"><strong>Versão atual: {activeDocument?.versao||latestDocument?.versao||1}</strong><Status>{activeDocument?"Ativa em homologação":p.status_nfse}</Status></div>{!blocked&&<div className="nfse-actions"><button className="secondary compact-button" onClick={()=>{setError("");setMessage("");setSubstitutingPayment(p)}}><RefreshCw size={16}/>Corrigir por substituição</button><button className="danger compact-button" onClick={()=>{setError("");setMessage("");setCancellingPayment(p)}}><Ban size={16}/>Cancelar teste</button></div>}</article>})}</div></section>}
  {correctingPayment&&<Modal title="Corrigir dados para reenvio" onClose={()=>{if(!correcting)setCorrectingPayment(null)}}><form key={correctingPayment.id} className="data-form" onSubmit={saveCorrection}><div className="notice warning"><ShieldCheck/><div><strong>A tentativa rejeitada será preservada</strong><span>Corrija os dados abaixo. O sistema exigirá nova validação e novos XMLs antes de permitir o reenvio.</span></div></div><p>Nota de <strong>{correctingPayment.alunos?.nome||`Aluno #${correctingPayment.aluno_id}`}</strong>.</p><div className="form-row"><label>Competência<input name="competencia" type="month" max={currentCompetenceInput()} defaultValue={competenceInput(correctingPayment.competencia)} required/></label><label>Valor da NFS-e<input name="valor" type="text" inputMode="numeric" defaultValue={money(correctingPayment.valor_nfse)} onInput={event=>event.currentTarget.value=currencyInput(event.currentTarget.value)} required/></label></div><label>Descrição do Serviço<textarea name="descricao_servico" rows={4} maxLength={1000} defaultValue={correctingPayment.descricao_servico||defaultServiceDescription(competenceInput(correctingPayment.competencia),correctingPayment.alunos?.segmento)} onInput={event=>event.currentTarget.value=upper(event.currentTarget.value)} required/></label><small>Os XMLs da tentativa anterior não serão apagados. A nota real continua desativada.</small><div className="form-actions"><button type="button" className="secondary" disabled={correcting} onClick={()=>setCorrectingPayment(null)}>Cancelar</button><button className="primary" disabled={correcting}>{correcting?"Salvando correção…":"Salvar e validar novamente"}</button></div></form></Modal>}
  {cancellingPayment&&<Modal title="Cancelar NFS-e de teste" onClose={()=>{if(!fiscalOperationBusy)setCancellingPayment(null)}}><form className="data-form homologation-form" onSubmit={cancelHomologationInvoice}><div className="notice warning"><Ban/><div><strong>O cancelamento não poderá ser desfeito</strong><span>A nota e seus XMLs continuarão no histórico, marcados como cancelados.</span></div></div><p>Cancelar a nota de <strong>{cancellingPayment.alunos?.nome||`Aluno #${cancellingPayment.aluno_id}`}</strong>, competência {cancellingPayment.competencia}.</p><label>Motivo<select name="reasonCode" defaultValue="1" required><option value="1">Erro na emissão</option><option value="2">Serviço não prestado</option><option value="9">Outros</option></select></label><label>Descrição do motivo<textarea name="reason" minLength={15} maxLength={255} rows={4} placeholder="Explique o motivo com pelo menos 15 caracteres" required/></label>{fiscalOperationBusy&&<TransmissionProgress kind="cancel"/>}<div className="form-actions"><button type="button" className="secondary" disabled={fiscalOperationBusy} onClick={()=>setCancellingPayment(null)}>Voltar</button><button className="danger" disabled={fiscalOperationBusy}><Ban size={17}/>{fiscalOperationBusy?"Cancelando…":"Confirmar cancelamento"}</button></div></form></Modal>}
  {substitutingPayment&&<Modal title="Corrigir por substituição" onClose={()=>{if(!fiscalOperationBusy)setSubstitutingPayment(null)}}><form className="data-form homologation-form" onSubmit={substituteHomologationInvoice}><div className="notice warning"><RefreshCw/><div><strong>Será gerada uma nova NFS-e</strong><span>A SEFIN cancelará a nota anterior por substituição e devolverá uma nova chave.</span></div></div><p>Revise os dados corrigidos da nota de <strong>{substitutingPayment.alunos?.nome||`Aluno #${substitutingPayment.aluno_id}`}</strong>.</p><div className="form-row"><label>Competência<input name="competencia" type="month" max={currentCompetenceInput()} defaultValue={competenceInput(substitutingPayment.competencia)} required/></label><label>Valor da nova NFS-e<input name="valor" type="text" inputMode="numeric" defaultValue={money(substitutingPayment.valor_nfse)} onInput={event=>event.currentTarget.value=currencyInput(event.currentTarget.value)} required/></label></div><label>Descrição corrigida do serviço<textarea name="descricao_servico" rows={4} maxLength={1000} defaultValue={substitutingPayment.descricao_servico||defaultServiceDescription(competenceInput(substitutingPayment.competencia),substitutingPayment.alunos?.segmento)} onInput={event=>event.currentTarget.value=upper(event.currentTarget.value)} required/></label><label>Motivo fiscal da substituição<select name="reasonCode" defaultValue="99" required><option value="01">Desenquadramento do Simples Nacional</option><option value="02">Enquadramento no Simples Nacional</option><option value="03">Inclusão retroativa de imunidade/isenção</option><option value="04">Exclusão retroativa de imunidade/isenção</option><option value="05">Rejeição pelo tomador ou intermediário</option><option value="99">Outros</option></select></label><label>Descrição do motivo<textarea name="reason" minLength={15} maxLength={255} rows={3} placeholder="Ex.: correção do valor ou da descrição do serviço" required/></label>{fiscalOperationBusy&&<TransmissionProgress kind="substitute"/>}<div className="form-actions"><button type="button" className="secondary" disabled={fiscalOperationBusy} onClick={()=>setSubstitutingPayment(null)}>Voltar</button><button className="primary" disabled={fiscalOperationBusy}><RefreshCw size={17}/>{fiscalOperationBusy?"Substituindo…":"Gerar nota substituta"}</button></div></form></Modal>}
  {preview&&<Modal title="Prévia da DPS de homologação" onClose={()=>setPreview(null)}><div className="dps-preview"><div className="notice warning"><ShieldCheck/><div><strong>Rascunho sem validade fiscal</strong><span>Ambiente 2 — Produção restrita. O XML será guardado no sistema, sem assinatura ou transmissão.</span></div></div><section><h3>Identificação da DPS</h3><dl><div><dt>Série / número</dt><dd>{preview.series} / {preview.number}</dd></div><div><dt>Competência</dt><dd>{preview.payment.competencia}</dd></div><div><dt>Município de emissão</dt><dd>3304557 — RIO DE JANEIRO/RJ</dd></div><div><dt>Leiaute</dt><dd>DPS 1.01 · Ambiente 2</dd></div></dl></section><section><h3>Prestador</h3><dl><div><dt>Razão social</dt><dd>{preview.company.razao_social}</dd></div><div><dt>CNPJ</dt><dd>{preview.company.cnpj}</dd></div><div><dt>Inscrição municipal</dt><dd>Não informada na NFS-e</dd></div></dl></section><section><h3>Tomador</h3><dl><div><dt>Responsável financeiro</dt><dd>{preview.payment.alunos?.responsavel}</dd></div><div><dt>CPF/CNPJ</dt><dd>{preview.payment.alunos?.cpf_cnpj}</dd></div><div><dt>E-mail</dt><dd>{preview.payment.alunos?.email}</dd></div><div><dt>Endereço</dt><dd>{[preview.payment.alunos?.logradouro,preview.payment.alunos?.numero,preview.payment.alunos?.complemento,preview.payment.alunos?.bairro,preview.payment.alunos?.cidade,preview.payment.alunos?.uf,preview.payment.alunos?.cep].filter(Boolean).join(", ")}</dd></div></dl></section><section><h3>Serviço e tributação</h3><label className="service-description-field">Descrição do Serviço<textarea rows={4} maxLength={1000} value={preview.description} onChange={e=>setPreview(current=>current?{...current,description:upper(e.target.value)}:current)} required/><small>Revise este texto. Ele ficará salvo para constar na futura nota.</small></label><dl><div><dt>Código</dt><dd>{preview.service.code} — {preview.service.description}</dd></div><div><dt>NBS</dt><dd>122012000</dd></div><div><dt>Valor do serviço</dt><dd>{money(preview.payment.valor_nfse)}</dd></div><div><dt>ISSQN</dt><dd>5,00% · Não retido · Tributável</dd></div><div><dt>Simples Nacional</dt><dd>Não optante</dd></div><div><dt>Regime tributário</dt><dd>Lucro Presumido</dd></div><div><dt>PIS</dt><dd>{percent(preview.company.pis_aliquota)}% · Apuração própria</dd></div><div><dt>COFINS</dt><dd>{percent(preview.company.cofins_aliquota)}% · Apuração própria</dd></div><div><dt>CST PIS/COFINS</dt><dd>{preview.company.pis_cofins_cst} · Operação tributável com alíquota básica</dd></div><div><dt>Retenções</dt><dd>PIS/COFINS/CSLL não retidos</dd></div></dl></section><div className="form-actions"><button className="secondary" onClick={()=>setPreview(null)}>Fechar</button>{preview.payment.status_nfse==="Prévia DPS aprovada"||preview.payment.status_nfse==="XML DPS preparado"||preview.payment.status_nfse==="XML DPS armazenado"?<button className="primary" disabled={generating} onClick={generateDpsXml}><CloudUpload size={17}/>{generating?"Guardando XML…":preview.payment.dps_xml_path?"Atualizar XML guardado":"Guardar XML no sistema"}</button>:<button className="primary" disabled={approving} onClick={approveDpsPreview}>{approving?"Gravando…":"Aprovar prévia"}</button>}</div></div></Modal>}
  {homologationPayment&&<Modal title="Emitir NFS-e de teste" onClose={closeHomologation}><form className="data-form homologation-form" onSubmit={sendToHomologation}><div className="notice warning"><ShieldCheck/><div><strong>Somente produção restrita</strong><span>Esta ação assina a DPS com o A1 e gera uma nota sem validade fiscal. A emissão real continua bloqueada.</span></div></div><p>A DPS de <strong>{homologationPayment.alunos?.nome||`Aluno #${homologationPayment.aluno_id}`}</strong> e o XML devolvido pelo ambiente nacional serão guardados de forma privada no sistema.</p><div className="notice compact"><ShieldCheck/><span>A senha protegida será recuperada pelo servidor somente durante a assinatura e nunca será exibida no navegador.</span></div>{sendingHomologation&&<TransmissionProgress kind="issue"/>}<div className="form-actions"><button type="button" className="secondary" disabled={sendingHomologation} onClick={closeHomologation}>Cancelar</button><button type="submit" className="primary" disabled={sendingHomologation}><Send size={17}/>{sendingHomologation?"Assinando e enviando…":"Gerar nota de teste"}</button></div></form></Modal>}
  {storedXml&&<Modal title={storedXml.title} onClose={()=>setStoredXml(null)}><div className="stored-xml"><div className="notice"><FileText/><div><strong>Arquivo privado no sistema online</strong><span>{storedXml.subtitle}</span></div></div><pre className="xml-viewer">{storedXml.xml}</pre><div className="form-actions"><button className="secondary" onClick={()=>setStoredXml(null)}>Fechar</button></div></div></Modal>}
 </>
}
